export const CSS = "\n  :root{\n    --green:#15A34A; --green-d:#0A5C30; --forest:#063D22; --forest-d:#042A17;\n    --orange:#F97316;\n    --white:#FFFFFF; --paper:#F6F8F6; --paper2:#EDF1EE;\n    --ink:#0E1512; --dim:#59635C; --hair:rgba(14,21,18,.11); --hair-2:rgba(14,21,18,.06);\n    --on-dark:#E9F2EC; --on-dark-dim:#8FA898;\n    --sh-sm:0 6px 20px -10px rgba(6,40,22,.18);\n    --sh-md:0 24px 55px -30px rgba(6,40,22,.35);\n    --sh-lg:0 50px 100px -45px rgba(6,40,22,.45);\n    --maxw:1200px;\n  }\n  .hl-landing{--display:var(--font-hl-display),system-ui,sans-serif;--body:var(--font-hl-body),system-ui,sans-serif}\n  .hl-landing *{box-sizing:border-box;margin:0;padding:0}\n  html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}\n  .hl-landing{direction:rtl;background:var(--white);color:var(--ink);font-family:var(--body);\n    line-height:1.6;-webkit-font-smoothing:antialiased;overflow-x:hidden;text-size-adjust:100%}\n  img,svg{max-width:100%;display:block}\n  a{color:inherit;text-decoration:none}\n  h1,h2,h3{font-family:var(--display);font-weight:800;letter-spacing:-.015em;text-wrap:balance;line-height:1.06}\n  .num{font-family:var(--display);font-variant-numeric:tabular-nums;font-feature-settings:\"tnum\"}\n  .wrap{width:100%;max-width:var(--maxw);margin:0 auto;padding-inline:clamp(18px,5vw,44px)}\n  section{position:relative}\n\n  /* buttons */\n  .btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;font-family:var(--display);\n    font-weight:700;font-size:15px;border-radius:999px;padding:13px 24px;min-height:46px;cursor:pointer;\n    border:1px solid transparent;transition:transform .12s,background .2s,box-shadow .2s,color .2s,border-color .2s;white-space:nowrap}\n  .btn:active{transform:scale(.97)}\n  .btn-primary{background:var(--green);color:#fff;box-shadow:0 12px 26px -12px rgba(21,163,74,.7)}\n  .btn-primary:hover{background:var(--green-d)}\n  .btn-line{border-color:var(--hair);color:var(--ink);background:transparent}\n  .btn-line:hover{border-color:var(--ink)}\n  .btn-ghost{color:var(--ink)} .btn-ghost:hover{color:var(--green)}\n  .btn-white{background:#fff;color:var(--green-d)} .btn-white:hover{background:#eef2ee}\n  .btn-onwhiteline{border-color:rgba(233,242,236,.4);color:#fff} .btn-onwhiteline:hover{background:rgba(255,255,255,.08)}\n  .btn-sm{padding:9px 18px;min-height:40px;font-size:14px}\n\n  /* logo */\n  .logo{display:inline-flex;align-items:flex-end;direction:ltr;font-size:1.35rem;line-height:1}\n  .logo svg{height:1.3em;width:auto;flex:none;align-self:flex-end;margin-bottom:.02em}\n  .logo .word{font-family:var(--display);font-weight:800;font-size:1em;letter-spacing:-.02em;line-height:1;\n    margin-inline-start:-.06em;margin-bottom:.02em;color:#1B4332}\n  .logo .period{color:var(--orange)}\n\n  /* ── HEADER ── */\n  header{position:sticky;top:0;z-index:60;background:rgba(255,255,255,.8);\n    backdrop-filter:blur(16px) saturate(180%);-webkit-backdrop-filter:blur(16px) saturate(180%);\n    border-bottom:1px solid transparent;transition:border-color .3s,box-shadow .3s}\n  header.solid{border-bottom-color:var(--hair)}\n  .bar{display:flex;align-items:center;justify-content:space-between;height:66px;gap:18px}\n  nav.main{display:flex;gap:28px;font-size:14.5px;font-weight:600;color:var(--dim)}\n  nav.main a{transition:color .2s} nav.main a:hover{color:var(--ink)}\n  .hactions{display:flex;align-items:center;gap:12px}\n  .menu-btn{display:none;background:none;border:none;padding:8px;cursor:pointer;color:var(--ink)}\n  @media(max-width:900px){\n    nav.main{display:none}\n    .hactions .btn-ghost{display:none}\n    .menu-btn{display:inline-flex}\n  }\n  /* mobile menu overlay */\n  .msheet{position:fixed;inset:0;z-index:70;background:#fff;display:flex;flex-direction:column;\n    padding:20px clamp(18px,6vw,32px) 32px;transform:translateY(-8px);opacity:0;pointer-events:none;\n    transition:opacity .25s,transform .25s;overflow-y:auto}\n  .msheet.open{opacity:1;transform:none;pointer-events:auto}\n  .msheet .mtop{display:flex;justify-content:space-between;align-items:center;height:66px}\n  .msheet nav{display:flex;flex-direction:column;margin-top:14px}\n  .msheet nav a{padding:16px 4px;font-family:var(--display);font-weight:700;font-size:1.15rem;\n    border-bottom:1px solid var(--hair-2)}\n  .msheet .mcta{display:flex;flex-direction:column;gap:12px;margin-top:24px}\n  .msheet .mcta .btn{width:100%}\n\n  /* ── HERO ── */\n  .hero{padding-top:clamp(48px,8vw,90px);padding-bottom:clamp(30px,5vw,50px);text-align:center;overflow:hidden;\n    background:radial-gradient(120% 80% at 50% -20%, rgba(21,163,74,.09), transparent 60%)}\n  .pill{display:inline-flex;align-items:center;gap:9px;font-size:13px;font-weight:700;color:var(--green-d);\n    background:rgba(21,163,74,.09);border:1px solid rgba(21,163,74,.2);border-radius:999px;padding:7px 16px}\n  .pill .pip{width:7px;height:7px;border-radius:50%;background:var(--orange)}\n  .hero h1{font-size:clamp(2.5rem,6.4vw,4.7rem);font-weight:900;margin-top:24px;max-width:16ch;margin-inline:auto;\n    letter-spacing:-.03em}\n  .hero .lead{color:var(--dim);font-size:clamp(16px,2.1vw,20px);max-width:52ch;margin:22px auto 0}\n  .hero .cta{display:flex;gap:12px;justify-content:center;margin-top:30px;flex-wrap:wrap}\n  .hero .fine{color:var(--dim);font-size:13px;margin-top:16px}\n\n  /* dashboard \"browser frame\" mock */\n  .frame{background:#fff;border:1px solid var(--hair);border-radius:16px;box-shadow:var(--sh-lg);overflow:hidden;\n    margin:clamp(34px,5vw,60px) auto 0;max-width:1040px;position:relative}\n  .frame .chrome{display:flex;align-items:center;gap:7px;padding:11px 15px;border-bottom:1px solid var(--hair-2);background:var(--paper)}\n  .frame .chrome i{width:11px;height:11px;border-radius:50%;background:#D6DAD7;display:block}\n  .frame .chrome .addr{margin-inline-start:12px;font-size:12px;color:var(--dim);background:#fff;border:1px solid var(--hair-2);\n    border-radius:7px;padding:4px 12px;direction:ltr}\n  .frame .body{padding:clamp(14px,2.4vw,24px)}\n  .hero .frame{transform:perspective(1600px) rotateX(2.2deg)}\n\n  .dashgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}\n  @media(max-width:640px){.dashgrid{grid-template-columns:1fr 1fr;gap:9px}}\n  .k{background:var(--paper);border:1px solid var(--hair-2);border-radius:13px;padding:13px 15px;text-align:start}\n  .k .kk{font-size:11.5px;color:var(--dim);font-weight:600;display:flex;align-items:center;gap:6px;flex-wrap:wrap}\n  .k .kv{font-family:var(--display);font-weight:800;font-size:clamp(1.15rem,2.4vw,1.6rem);margin-top:3px}\n  .k .kv.green{color:var(--green)}\n  .tag{font-size:10.5px;font-weight:700;padding:1px 6px;border-radius:6px}\n  .tag.up{color:var(--green);background:rgba(21,163,74,.12)} .tag.down{color:#C2410C;background:rgba(249,115,22,.12)}\n  .chartbox{margin-top:12px;background:var(--paper);border:1px solid var(--hair-2);border-radius:14px;padding:14px 12px 10px;position:relative}\n  .chartbox .cl{font-size:11.5px;color:var(--dim);font-weight:600;margin-bottom:4px;text-align:start;padding-inline-start:4px}\n  .legend{display:flex;gap:14px;font-size:11px;color:var(--dim);padding-inline-start:4px;margin-top:4px}\n  .legend .lg::before{content:\"\";display:inline-block;width:9px;height:9px;border-radius:50%;margin-inline-end:5px;vertical-align:middle}\n  .legend .rev::before{background:var(--green)} .legend .prof::before{background:var(--orange)}\n  .gaptag{position:absolute;background:var(--forest);color:#fff;font-size:11px;font-weight:700;font-family:var(--display);\n    padding:4px 9px;border-radius:8px;white-space:nowrap;pointer-events:none}\n\n  /* ── LOGO STRIP ── */\n  .strip{padding:clamp(30px,4vw,44px) 0;border-top:1px solid var(--hair-2);border-bottom:1px solid var(--hair-2)}\n  .strip .lab{text-align:center;color:var(--dim);font-size:13px;font-weight:600;letter-spacing:.02em;margin-bottom:20px}\n  .strip .row{display:flex;flex-wrap:wrap;gap:clamp(20px,5vw,52px);justify-content:center;align-items:center;\n    opacity:.62;filter:grayscale(1)}\n  .strip .brand{font-family:var(--display);font-weight:800;font-size:clamp(1rem,2.6vw,1.4rem);color:var(--ink);letter-spacing:-.01em}\n\n  /* ── STATS BAND (Adyen) ── */\n  .stats{background:var(--forest);color:var(--on-dark);padding:clamp(52px,8vw,96px) 0;\n    background:radial-gradient(90% 120% at 85% -10%, rgba(21,163,74,.28), transparent 55%),linear-gradient(180deg,var(--forest),var(--forest-d))}\n  .stats h2{color:#fff;font-size:clamp(1.7rem,3.6vw,2.6rem);max-width:20ch}\n  .stats .sub{color:var(--on-dark-dim);margin-top:12px;max-width:52ch;font-size:clamp(15px,1.9vw,17px)}\n  .statgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:clamp(16px,3vw,28px);margin-top:clamp(34px,5vw,52px)}\n  @media(max-width:820px){.statgrid{grid-template-columns:1fr 1fr;gap:26px}}\n  .stat .sv{font-family:var(--display);font-weight:900;font-size:clamp(2.1rem,5vw,3.4rem);color:#fff;letter-spacing:-.03em;line-height:1}\n  .stat .sv .u{color:#57E28C}\n  .stat .sl{color:var(--on-dark-dim);font-size:14px;margin-top:8px}\n\n  /* ── SECTION scaffolding ── */\n  .band{padding:clamp(60px,9vw,120px) 0}\n  .band.paper{background:var(--paper)}\n  .eyebrow{display:inline-flex;align-items:center;gap:8px;font-size:12px;font-weight:700;letter-spacing:.06em;\n    text-transform:uppercase;color:var(--green-d)}\n  .eyebrow::before{content:none}\n  .sh{font-size:clamp(1.9rem,4.2vw,3rem);margin-top:16px;max-width:20ch}\n  .ssub{color:var(--dim);font-size:clamp(15px,1.9vw,18px);max-width:56ch;margin-top:16px}\n  .center{text-align:center;display:flex;flex-direction:column;align-items:center}\n\n  /* steps */\n  .steps{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:clamp(34px,5vw,54px)}\n  @media(max-width:820px){.steps{grid-template-columns:1fr}}\n  .step{background:#fff;border:1px solid var(--hair);border-radius:18px;padding:28px;position:relative}\n  .band.paper .step{background:#fff}\n  .step .n{font-family:var(--display);font-weight:800;font-size:13px;color:var(--orange);letter-spacing:.1em}\n  .step h3{font-size:1.3rem;margin-top:12px}\n  .step p{color:var(--dim);font-size:14.5px;margin-top:8px}\n  .step .ic{width:44px;height:44px;border-radius:12px;display:grid;place-items:center;background:rgba(21,163,74,.1);color:var(--green);margin-bottom:16px}\n\n  /* showcase (two-col alt) */\n  .show{display:grid;grid-template-columns:1fr 1fr;gap:clamp(28px,5vw,64px);align-items:center;margin-top:clamp(40px,6vw,72px)}\n  @media(max-width:900px){.show{grid-template-columns:1fr;gap:28px}.show.rev .txt{order:-1}}\n  .show .txt h3{font-size:clamp(1.5rem,3vw,2.1rem)}\n  .show .txt p{color:var(--dim);font-size:clamp(15px,1.8vw,17px);margin-top:14px}\n  .show .txt ul{list-style:none;margin-top:18px;display:flex;flex-direction:column;gap:11px}\n  .show .txt li{display:flex;gap:10px;font-size:15px}\n  .show .txt li svg{color:var(--green);flex:none;margin-top:3px}\n  .show .art{background:#fff;border:1px solid var(--hair);border-radius:18px;box-shadow:var(--sh-md);overflow:hidden}\n  .show .art .chrome{display:flex;gap:6px;padding:10px 13px;border-bottom:1px solid var(--hair-2);background:var(--paper)}\n  .show .art .chrome i{width:10px;height:10px;border-radius:50%;background:#D6DAD7}\n  .show .art .inner{padding:clamp(14px,2.2vw,22px)}\n\n  /* top products table */\n  .ptable{width:100%;border-collapse:collapse;font-size:13.5px}\n  .ptable th{text-align:start;color:var(--dim);font-weight:600;font-size:11.5px;padding:7px 8px;border-bottom:1px solid var(--hair)}\n  .ptable td{padding:9px 8px;border-bottom:1px solid var(--hair-2)}\n  .ptable .p{font-weight:600}\n  .ptable .rev{font-family:var(--display);font-weight:700;font-variant-numeric:tabular-nums}\n  .ptable .prof{font-family:var(--display);font-weight:800;font-variant-numeric:tabular-nums}\n  .ptable .prof.lo{color:#C2410C} .ptable .prof.hi{color:var(--green)}\n  .ptable tr.flag td{background:rgba(249,115,22,.06)}\n  .tbl-note{font-size:12.5px;color:var(--dim);margin-top:10px;display:flex;align-items:center;gap:7px}\n\n  /* agent cards (draggable) */\n  .agent-stage{position:relative;height:330px;border-radius:18px;overflow:hidden;touch-action:pan-y;cursor:grab;user-select:none;-webkit-user-select:none}\n  .agent-stage:active{cursor:grabbing}\n  @media(max-width:520px){.agent-stage{height:390px}}\n  .fcard{position:absolute;inset:0;will-change:transform,opacity;border-radius:18px;padding:clamp(20px,3vw,30px);\n    display:flex;flex-direction:column;border:1px solid var(--hair);box-shadow:var(--sh-sm)}\n  .fcard.blue{background:linear-gradient(180deg,#F2F8FF,#fff)} .fcard.red{background:linear-gradient(180deg,#FEF4F2,#fff)} .fcard.amber{background:linear-gradient(180deg,#FEFAEE,#fff)}\n  .fcard .frow{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;flex-wrap:wrap}\n  .fcard .ft{font-family:var(--display);font-weight:800;font-size:clamp(1.05rem,2.2vw,1.35rem)}\n  .fcard.blue .ft{color:#1D4ED8} .fcard.red .ft{color:#C2410C} .fcard.amber .ft{color:#A16207}\n  .chips{display:flex;gap:6px;flex-wrap:wrap}\n  .chip{font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;border:1px solid var(--hair);color:var(--dim);background:rgba(255,255,255,.7)}\n  .blk{margin-top:13px;background:rgba(255,255,255,.6);border:1px solid var(--hair);border-radius:12px;padding:12px 14px}\n  .blk .bl{font-size:10.5px;font-weight:700;letter-spacing:.05em;color:var(--dim);text-transform:uppercase}\n  .blk .bt{font-size:14px;margin-top:4px;line-height:1.5}\n  .blk .bt .mono{font-family:var(--display);font-weight:700;font-variant-numeric:tabular-nums}\n  .learned{margin-top:auto;padding-top:12px;font-size:12.5px;color:var(--dim);display:flex;align-items:center;gap:7px}\n  .learned svg{color:var(--green);flex:none}\n  .pager{display:flex;justify-content:center;gap:9px;margin-top:18px}\n  .dot{height:8px;width:8px;border-radius:999px;border:none;padding:0;cursor:pointer;background:rgba(14,21,18,.2);transition:width .35s,background .35s,transform .2s}\n  .dot[aria-current=\"true\"]{width:26px;background:var(--orange)}\n  .dot:active{transform:scale(.86)}\n  .draghint{text-align:center;color:var(--dim);font-size:12.5px;margin-top:10px;display:flex;align-items:center;justify-content:center;gap:7px}\n\n  /* video slot */\n  .vslot{margin-top:clamp(34px,5vw,54px);aspect-ratio:16/9;border-radius:20px;position:relative;overflow:hidden;\n    background:linear-gradient(140deg,var(--forest),var(--forest-d));display:grid;place-items:center;box-shadow:var(--sh-md);\n    border:1px dashed rgba(233,242,236,.3)}\n  .vslot .play{width:74px;height:74px;border-radius:50%;background:rgba(255,255,255,.14);backdrop-filter:blur(6px);\n    display:grid;place-items:center;border:1px solid rgba(255,255,255,.35)}\n  .vslot .play svg{color:#fff;margin-inline-start:4px}\n  .vslot .vlabel{position:absolute;bottom:16px;inset-inline-start:20px;color:var(--on-dark);font-size:13px;font-weight:600}\n  .vslot .vtag{position:absolute;top:16px;inset-inline-end:20px;color:var(--on-dark-dim);font-size:11.5px;font-weight:700;\n    letter-spacing:.06em;text-transform:uppercase;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);border-radius:999px;padding:5px 12px}\n\n  /* testimonial */\n  .quote{background:#fff;border:1px solid var(--hair);border-radius:22px;padding:clamp(30px,5vw,56px);text-align:center;\n    max-width:840px;margin:clamp(34px,5vw,50px) auto 0;box-shadow:var(--sh-sm)}\n  .quote p{font-family:var(--display);font-weight:600;font-size:clamp(1.25rem,2.8vw,1.9rem);line-height:1.4;letter-spacing:-.01em}\n  .quote .who{margin-top:20px;color:var(--dim);font-size:14px}\n  .quote .who b{color:var(--ink);font-family:var(--display)}\n\n  /* pricing */\n  .plans{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:clamp(34px,5vw,48px);align-items:stretch}\n  @media(max-width:820px){.plans{grid-template-columns:1fr;max-width:440px;margin-inline:auto}}\n  .plan{background:#fff;border:1px solid var(--hair);border-radius:20px;padding:30px;display:flex;flex-direction:column;position:relative}\n  .plan.pop{border-color:var(--green);box-shadow:0 34px 66px -34px rgba(21,163,74,.42)}\n  .plan .b{position:absolute;top:-13px;inset-inline-start:30px;background:var(--orange);color:#fff;font-family:var(--display);font-weight:700;font-size:11px;padding:4px 12px;border-radius:999px}\n  .plan h3{font-size:1.35rem} .plan .bl{color:var(--dim);font-size:13px;margin-top:4px}\n  .plan .price{font-family:var(--display);font-weight:900;font-size:2.5rem;margin-top:18px;letter-spacing:-.02em}\n  .plan .price small{font-size:.85rem;font-weight:500;color:var(--dim)}\n  .plan ul{list-style:none;margin:18px 0;display:flex;flex-direction:column;gap:11px;flex:1}\n  .plan li{display:flex;gap:9px;font-size:14.5px} .plan li svg{color:var(--green);flex:none;margin-top:3px}\n  .plan li.no{color:var(--dim)} .plan li.no svg{color:var(--dim)}\n  .plan .price.free{color:var(--green)}\n  .plan .creditline{display:inline-block;margin-top:8px;font-size:11.5px;font-weight:700;color:#C2410C;background:rgba(249,115,22,.1);border-radius:999px;padding:3px 11px}\n  .price-foot{text-align:center;color:var(--dim);font-size:13px;margin-top:26px}\n\n  /* security */\n  .secgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:36px}\n  @media(max-width:820px){.secgrid{grid-template-columns:1fr 1fr}}\n  .seccell{background:rgba(255,255,255,.05);border:1px solid rgba(233,242,236,.16);border-radius:16px;padding:22px}\n  .seccell .st{font-family:var(--display);font-weight:800;font-size:1.05rem;color:#fff}\n  .seccell .sd{color:var(--on-dark-dim);font-size:13px;margin-top:7px;line-height:1.5}\n\n  /* final */\n  .final{background:linear-gradient(155deg,var(--green),var(--green-d));color:#fff;border-radius:30px;\n    padding:clamp(44px,7vw,84px);text-align:center;box-shadow:var(--sh-lg);position:relative;overflow:hidden}\n  .final::before{content:\"\";position:absolute;inset:0;background:radial-gradient(70% 60% at 82% 0%,rgba(255,255,255,.2),transparent 60%)}\n  .final h2{font-size:clamp(2rem,4.4vw,3.2rem);position:relative} .final p{color:rgba(255,255,255,.92);margin-top:14px;font-size:clamp(15px,1.9vw,18px);position:relative}\n  .final .cta{display:flex;gap:12px;justify-content:center;margin-top:30px;position:relative;flex-wrap:wrap}\n\n  footer{background:var(--forest-d);color:var(--on-dark-dim);padding:clamp(44px,6vw,70px) 0 30px;font-size:14px}\n  .fgrid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:30px}\n  @media(max-width:760px){.fgrid{grid-template-columns:1fr 1fr}}\n  @media(max-width:460px){.fgrid{grid-template-columns:1fr 1fr}}\n  footer h4{color:#fff;font-family:var(--display);font-size:13px;letter-spacing:.04em;text-transform:uppercase;margin-bottom:14px}\n  footer a{display:block;padding:6px 0;transition:color .2s} footer a:hover{color:#fff}\n  footer .fbottom{margin-top:40px;padding-top:22px;border-top:1px solid rgba(233,242,236,.14);\n    display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;align-items:center}\n\n  /* scroll-driven text color reveal (Adyen-style) */\n  .reveal-text{font-family:var(--display);font-weight:800;letter-spacing:-.02em;line-height:1.28;\n    font-size:clamp(1.6rem,4.2vw,3rem);max-width:22ch;margin-inline:auto;text-align:center}\n  .reveal-text .rw{color:rgba(14,21,18,.16);transition:color .35s ease}\n  .reveal-text .rw.on{color:var(--ink)}\n  .reveal-text .rw.accent.on{color:var(--green)}\n\n  /* horizontal media carousel (Adyen-style) */\n  .tour-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;flex-wrap:wrap;margin-top:clamp(30px,4vw,46px)}\n  .cnav{display:flex;gap:9px}\n  .cbtn{width:46px;height:46px;border-radius:50%;border:1px solid var(--hair);background:#fff;cursor:pointer;\n    display:grid;place-items:center;color:var(--ink);transition:transform .12s,border-color .2s,opacity .2s}\n  .cbtn:hover{border-color:var(--ink)} .cbtn:active{transform:scale(.93)}\n  .cbtn:disabled{opacity:.3;cursor:default;border-color:var(--hair)}\n  .carousel{display:flex;gap:16px;overflow-x:auto;scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;\n    padding:20px 0 10px;scrollbar-width:none;margin-top:14px}\n  .carousel::-webkit-scrollbar{display:none}\n  .cslide{scroll-snap-align:start;flex:0 0 auto;width:min(80vw,380px);display:flex;flex-direction:column}\n  .cslide .media{aspect-ratio:16/11;border-radius:16px;overflow:hidden;position:relative;box-shadow:var(--sh-md);border:1px solid var(--hair)}\n  .cslide .media img{width:100%;height:100%;object-fit:cover;object-position:top center}\n  .cslide .media.vid{background:linear-gradient(140deg,var(--forest),var(--forest-d));display:grid;place-items:center;border:1px solid rgba(233,242,236,.2)}\n  .cslide .media .play{width:64px;height:64px;border-radius:50%;background:rgba(255,255,255,.16);backdrop-filter:blur(6px);\n    -webkit-backdrop-filter:blur(6px);display:grid;place-items:center;border:1px solid rgba(255,255,255,.4)}\n  .cslide .media .play svg{color:#fff;margin-inline-start:4px}\n  .cslide .media .vtag{position:absolute;top:14px;inset-inline-end:14px;color:var(--on-dark-dim);font-size:10.5px;font-weight:700;\n    letter-spacing:.05em;text-transform:uppercase;background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.2);border-radius:999px;padding:4px 10px}\n  .cslide .media .shot-tag{position:absolute;top:14px;inset-inline-end:14px;background:rgba(255,255,255,.92);color:var(--green-d);\n    font-size:10.5px;font-weight:700;border-radius:999px;padding:4px 10px;box-shadow:var(--sh-sm)}\n  .cslide h3{font-size:1.2rem;margin-top:16px}\n  .cslide p{color:var(--dim);font-size:14px;margin-top:6px}\n\n  /* \"numbers → clarity\" converge visual (the slogan, made literal) */\n  .cv{position:relative;height:clamp(400px,60vw,540px);margin-top:clamp(30px,4vw,48px)}\n  .cv canvas{position:absolute;inset:0;width:100%;height:100%}\n  .cv .src{position:absolute;transform:translate(-50%,-50%);display:inline-flex;align-items:center;gap:7px;\n    background:#fff;border:1px solid var(--hair);border-radius:999px;padding:7px 13px;font-family:var(--display);\n    font-weight:700;font-size:clamp(11px,2.3vw,13.5px);box-shadow:var(--sh-sm);white-space:nowrap;z-index:2;color:var(--ink)}\n  .cv .src .d{width:8px;height:8px;border-radius:50%;background:var(--green);flex:none}\n  .cv .src .ic{width:19px;height:19px;flex:none}\n  /* central brain / hub node */\n  .cv .core{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);z-index:3;\n    display:flex;flex-direction:column;align-items:center;gap:12px}\n  .hub{position:relative;width:clamp(128px,27vw,174px);height:clamp(128px,27vw,174px);display:grid;place-items:center}\n  .hub .glow{position:absolute;inset:-16%;border-radius:50%;background:radial-gradient(circle,rgba(21,163,74,.30),transparent 66%);filter:blur(4px);z-index:0}\n  .hub .ring{position:absolute;border-radius:50%;border:1.5px dashed rgba(21,163,74,.38);z-index:1}\n  .hub .r1{inset:0;animation:hubspin 22s linear infinite}\n  .hub .r2{inset:17%;border-color:rgba(249,115,22,.42);animation:hubspin 14s linear infinite reverse}\n  .hub .nd{position:absolute;width:9px;height:9px;border-radius:50%;background:var(--green);box-shadow:0 0 0 4px rgba(21,163,74,.14)}\n  .hub .r2 .nd{background:var(--orange);box-shadow:0 0 0 4px rgba(249,115,22,.14)}\n  .hub .pulse{position:absolute;inset:9%;border-radius:50%;border:2px solid rgba(21,163,74,.45);z-index:1;animation:hubpulse 2.8s ease-out infinite}\n  .hub .disc{position:relative;width:56%;height:56%;border-radius:50%;background:linear-gradient(180deg,#fff,#eef5ef);\n    border:1px solid var(--hair);box-shadow:var(--sh-md);display:grid;place-items:center;z-index:3}\n  .hub .disc svg{width:60%;height:60%}\n  .hub-cap{display:inline-flex;align-items:center;gap:7px;background:#fff;border:1px solid var(--hair);border-radius:999px;\n    padding:6px 14px;box-shadow:var(--sh-sm);font-family:var(--display);font-weight:700;font-size:13px;color:var(--ink);z-index:3;white-space:nowrap}\n  .hub-cap .dot{width:7px;height:7px;border-radius:50%;background:var(--green);box-shadow:0 0 0 3px rgba(21,163,74,.15)}\n  @keyframes hubspin{to{transform:rotate(360deg)}}\n  @keyframes hubpulse{0%{transform:scale(.7);opacity:.7}100%{transform:scale(1.4);opacity:0}}\n  @media(max-width:520px){.cv .src{font-size:10.5px;padding:5px 9px}.cv .src .ic{width:17px;height:17px}}\n  @media (prefers-reduced-motion: reduce){.hub .r1,.hub .r2,.hub .pulse{animation:none}.flow-arrow .ln{animation:none}}\n\n  /* blur→sharp: \"make your vision clear\" */\n  .frame.reveal{filter:blur(11px)}\n  .frame.reveal.in{filter:blur(0)}\n\n  /* recreated mini dashboards inside carousel cards (fabricated demo data) */\n  .mk{position:absolute;inset:0;background:#fff;padding:12px;display:flex;flex-direction:column;gap:8px}\n  .mk .mtitle{font-family:var(--display);font-weight:700;font-size:11px;color:var(--dim);display:flex;justify-content:space-between;align-items:center}\n  .mk .mtitle .live{display:inline-flex;align-items:center;gap:5px;color:var(--green);font-size:9px;font-weight:700}\n  .mk .mtitle .live::before{content:\"\";width:6px;height:6px;border-radius:50%;background:var(--green)}\n  .mk .mkpis{display:flex;gap:7px}\n  .mk .mkp{flex:1;background:var(--paper);border:1px solid var(--hair-2);border-radius:9px;padding:7px 9px}\n  .mk .mkp .a{font-size:8.5px;color:var(--dim);font-weight:600}\n  .mk .mkp .b{font-family:var(--display);font-weight:800;font-size:14px;margin-top:1px}\n  .mk .mkp .b.g{color:var(--green)}\n  .mk .mchart{flex:1;background:var(--paper);border:1px solid var(--hair-2);border-radius:10px;overflow:hidden;position:relative;min-height:64px}\n  .mk .mchart svg{position:absolute;inset:0;width:100%;height:100%}\n  .mk.agent{background:linear-gradient(180deg,#F2F8FF,#fff);padding:14px}\n  .mk .acard{background:#fff;border:1px solid var(--hair);border-radius:12px;padding:12px;display:flex;flex-direction:column;gap:8px;height:100%}\n  .mk .arow{display:flex;justify-content:space-between;align-items:center;gap:8px}\n  .mk .at{font-family:var(--display);font-weight:800;font-size:13px;color:#1D4ED8}\n  .mk .achip{font-size:9px;font-weight:700;color:var(--dim);border:1px solid var(--hair);border-radius:999px;padding:3px 9px;white-space:nowrap}\n  .mk .ablk{background:rgba(255,255,255,.75);border:1px solid var(--hair);border-radius:9px;padding:8px 10px;font-size:11px;line-height:1.5}\n  .mk .ablk .l{font-size:8px;font-weight:700;color:var(--dim);text-transform:uppercase;letter-spacing:.04em}\n  .mk .ablk .mono{font-family:var(--display);font-weight:700}\n  .mk table{width:100%;border-collapse:collapse;font-size:11px}\n  .mk th{color:var(--dim);font-weight:600;font-size:8.5px;text-align:start;padding:3px 6px;border-bottom:1px solid var(--hair)}\n  .mk td{padding:6px;border-bottom:1px solid var(--hair-2)}\n  .mk td.n{font-family:var(--display);font-weight:700;font-variant-numeric:tabular-nums}\n  .mk td.lo{color:#C2410C} .mk td.hi{color:var(--green)}\n  .mk tr.fl td{background:rgba(249,115,22,.07)}\n\n  .cv .cluster-tag{position:absolute;transform:translate(-50%,-50%);font-family:var(--display);font-weight:800;font-size:11px;color:var(--dim);z-index:2;opacity:.75;letter-spacing:.02em;pointer-events:none}\n  .flow{display:flex;flex-direction:column;align-items:center;gap:8px;margin-top:2px}\n  .flow-arrow{width:32px;height:104px}\n  .flow-arrow .ln{stroke:var(--green);stroke-width:2;stroke-dasharray:4 5;animation:flowdash 1s linear infinite}\n  @keyframes flowdash{to{stroke-dashoffset:-18}}\n  .flow-lbl{font-family:var(--display);font-weight:700;font-size:13.5px;color:var(--dim)}\n  .acts{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:20px}\n  @media(max-width:820px){.acts{grid-template-columns:1fr;max-width:520px;margin-inline:auto}}\n  .act{display:flex;gap:13px;align-items:stretch;background:#fff;border:1px solid var(--hair);border-radius:16px;padding:20px 18px;box-shadow:var(--sh-sm);position:relative}\n  .act::before{content:\"\";position:absolute;inset-inline-start:0;top:16px;bottom:16px;width:3px;border-radius:0 3px 3px 0;background:var(--green)}\n  .act.orange::before{background:var(--orange)}\n  .act .aic{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;flex:none;background:rgba(21,163,74,.1);color:var(--green)}\n  .act.orange .aic{background:rgba(249,115,22,.1);color:var(--orange)}\n  .act .atx{display:flex;flex-direction:column;flex:1;min-width:0}\n  .act .atx b{font-family:var(--display);font-weight:700;font-size:15px;line-height:1.3;display:block;min-height:2.6em}\n  @media(max-width:820px){.act .atx b{min-height:0}}\n  .act .atx p{color:var(--dim);font-size:13px;margin-top:6px;line-height:1.55}\n  .act .imp{align-self:flex-start;margin-top:12px;font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;background:rgba(21,163,74,.12);color:var(--green-d)}\n  .act.orange .imp{background:rgba(249,115,22,.12);color:#C2410C}\n  /* converge visual: dedicated mobile layout (ring → stacked) */\n  @media(max-width:640px){\n    .cv{height:540px}\n    .cv .src{font-size:10.5px;padding:5px 8px;gap:5px}\n    .cv .src .ic{width:15px;height:15px}\n    .hub{width:110px;height:110px}\n    .hub-cap{font-size:11px;padding:5px 10px}\n    .cv .cluster-tag{display:none}\n  }\n  .plans{grid-template-columns:repeat(4,1fr)}\n  @media(max-width:1000px){.plans{grid-template-columns:repeat(2,1fr);max-width:660px;margin-inline:auto}}\n  @media(max-width:560px){.plans{grid-template-columns:1fr;max-width:420px}}\n  .plan{padding:26px 20px} .plan .price{font-size:2.1rem}\n  .pricetoggle{display:flex;justify-content:center;margin-top:22px}\n  .pricetoggle .seg{display:inline-flex;background:var(--paper2);border:1px solid var(--hair);border-radius:999px;padding:4px;gap:2px}\n  .pricetoggle button{font-family:var(--display);font-weight:700;font-size:13px;border:none;background:transparent;color:var(--dim);padding:9px 17px;border-radius:999px;cursor:pointer;transition:background .2s,color .2s,transform .1s}\n  .pricetoggle button:active{transform:scale(.96)}\n  .pricetoggle button[aria-current=\"true\"]{background:#fff;color:var(--ink);box-shadow:var(--sh-sm)}\n  .flatchip{display:inline-flex;align-items:center;gap:8px;margin-top:16px;font-size:12.5px;font-weight:700;color:var(--green-d);background:rgba(21,163,74,.09);border:1px solid rgba(21,163,74,.2);border-radius:999px;padding:7px 15px}\n  .flatchip .pip{width:7px;height:7px;border-radius:50%;background:var(--orange)}\n  .plan .price .note{display:none;font-size:11px;font-weight:600;color:var(--dim);margin-top:2px}\n  .plan li.allow{font-weight:600} .plan li.allow svg{color:var(--orange)}\n  .frame .body{background:linear-gradient(180deg,#F6F8F6,#fff)}\n  .kpigrid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}\n  @media(max-width:640px){.kpigrid{grid-template-columns:1fr 1fr}}\n  .kpi-card{background:#fff;border:1px solid var(--hair-2);border-radius:14px;padding:13px 14px}\n  .kc-top{display:flex;justify-content:space-between;align-items:flex-start;gap:8px}\n  .kc-ic{width:30px;height:30px;border-radius:9px;display:grid;place-items:center;background:rgba(21,163,74,.1);color:var(--green);flex:none}\n  .kc-ic svg{width:16px;height:16px}\n  .kc-delta{font-size:10px;font-weight:700;padding:2px 7px;border-radius:7px;white-space:nowrap}\n  .kc-delta.up{color:var(--green);background:rgba(21,163,74,.12)}\n  .kc-delta.down{color:#C2410C;background:rgba(249,115,22,.12)}\n  .kc-label{font-size:11px;color:var(--dim);font-weight:600;margin-top:11px}\n  .kc-val{font-family:var(--display);font-weight:800;font-size:clamp(1.15rem,2.5vw,1.6rem);margin-top:2px;line-height:1.1}\n  .kc-val.green{color:var(--green)}\n  .kc-desc{font-size:10.5px;color:var(--dim);margin-top:5px;line-height:1.4}\n  @media(max-width:640px){.kc-desc{display:none}}\n  .mk.leak{padding:13px;gap:7px;justify-content:flex-start}\n  .leak-eyebrow{font-size:8.5px;font-weight:700;letter-spacing:.06em;color:var(--green-d)}\n  .leak-hero{font-family:var(--display);font-weight:800;font-size:15px;line-height:1.2;margin-bottom:2px}\n  .leak-hero .amt{color:var(--orange)}\n  .leak-row{display:flex;align-items:center;gap:8px;background:rgba(249,115,22,.06);border-radius:9px;padding:7px 9px}\n  .leak-row.ok{background:rgba(21,163,74,.06)}\n  .lr-ic{width:17px;height:17px;border-radius:50%;display:grid;place-items:center;font-size:10px;font-weight:800;flex:none}\n  .lr-ic.warn{background:rgba(249,115,22,.16);color:#C2410C}\n  .lr-ic.ok{background:rgba(21,163,74,.16);color:var(--green)}\n  .lr-tx{flex:1;display:flex;flex-direction:column;line-height:1.25;min-width:0}\n  .lr-tx b{font-weight:700;font-size:10.5px}\n  .lr-tx span{color:var(--dim);font-size:9px}\n  .lr-amt{font-family:var(--display);font-weight:800;color:#C2410C;font-size:12px;flex:none}\n  .videofeature{max-width:min(640px,92vw);margin:clamp(26px,4vw,44px) auto 0;border-radius:18px;overflow:hidden;box-shadow:var(--sh-lg);aspect-ratio:16/9;background:#000}\n  .videofeature video{width:100%;height:100%;object-fit:cover;display:block}\n  .hero{text-align:right}\n  .hero-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(28px,5vw,56px);align-items:center;padding-top:clamp(16px,3vw,30px)}\n  .hero-text h1{max-width:none;margin:0}\n  .hero-text .lead{max-width:48ch;margin-inline-start:0;margin-inline-end:0}\n  .hero-text .cta{justify-content:flex-start}\n  .hero-text .fine{text-align:right}\n  .hero-media{border-radius:18px;overflow:hidden;box-shadow:var(--sh-lg);aspect-ratio:16/9;background:#000}\n  .hero-media video{width:100%;height:100%;object-fit:cover;display:block}\n  @media(max-width:900px){\n    .hero-grid{grid-template-columns:1fr;text-align:center}\n    .hero-text{text-align:center}\n    .hero-text .lead{margin-inline:auto}\n    .hero-text .cta{justify-content:center}\n    .hero-text .fine{text-align:center}\n    .hero-media{margin-top:6px}\n  }\n  .eyebrow,.sec-eyebrow{display:none}\n  @media(min-width:901px){\n    .hero-grid{grid-template-columns:0.78fr 1.22fr}\n    .hero-text h1{font-size:clamp(1.9rem,4.2vw,3.3rem)}\n  }\n  .vsviz{margin-top:16px;display:flex;flex-direction:column;gap:14px}\n  .vv{background:var(--paper);border:1px solid var(--hair);border-radius:14px;padding:14px 16px}\n  .vv-top{display:flex;align-items:center;gap:8px;margin-bottom:8px}\n  .vv-name{font-family:var(--display);font-weight:700;font-size:14px}\n  .vv-badge{font-size:10.5px;font-weight:700;color:#C2410C;background:rgba(249,115,22,.12);border-radius:999px;padding:2px 9px}\n  .vv-bar{display:grid;grid-template-columns:1fr auto;gap:9px;align-items:center;margin-top:7px}\n  .vv-track{background:rgba(23,32,27,.08);border-radius:999px;height:11px;overflow:hidden}\n  .vv-track i{display:block;height:100%;border-radius:999px;transition:width 1.1s cubic-bezier(.2,.7,.2,1)}\n  .vv-track i.rev{background:rgba(23,32,27,.28)} .vv-track i.prof{background:var(--green)}\n  .vv-bar b{font-family:var(--display);font-weight:700;font-size:12px;color:var(--dim);white-space:nowrap;font-variant-numeric:tabular-nums}\n  .vv-cap{font-size:12px;color:var(--dim);display:flex;gap:14px;margin-top:2px}\n  .vv-cap span{display:inline-flex;align-items:center;gap:5px}\n  .vv-cap i{width:9px;height:9px;border-radius:3px;display:inline-block}\n  .cv canvas{z-index:1}\n  .reveal{opacity:0;transform:translateY(24px);transition:opacity .7s cubic-bezier(.2,.7,.2,1),transform .7s cubic-bezier(.2,.7,.2,1),filter .9s ease}\n  .reveal.in{opacity:1;transform:none}\n  @media (prefers-reduced-motion: reduce){\n    html{scroll-behavior:auto}\n    *{transition-duration:.001ms !important;animation-duration:.001ms !important}\n    .reveal{opacity:1;transform:none;filter:none}.draghint{display:none}.hero .frame{transform:none}\n  }\n";

