export function initCompanyLanding() {

/* header solid on scroll */
addEventListener('scroll',()=>{document.getElementById('header').classList.toggle('solid',scrollY>10)},{passive:true});

/* mobile menu */
const msheet=document.getElementById('msheet');
const openM=()=>{msheet.classList.add('open');document.body.style.overflow='hidden'};
const closeM=()=>{msheet.classList.remove('open');document.body.style.overflow=''};
document.getElementById('menuBtn').addEventListener('click',openM);
document.getElementById('menuClose').addEventListener('click',closeM);
msheet.querySelectorAll('[data-close]').forEach(a=>a.addEventListener('click',closeM));

/* reveal */
const revIO=new IntersectionObserver((es)=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');revIO.unobserve(e.target)}}),{threshold:.12});
document.querySelectorAll('.reveal').forEach(el=>revIO.observe(el));

/* count-up */
function countUp(el){const to=parseFloat(el.dataset.count),dec=+(el.dataset.dec||0),pre=el.dataset.prefix||'',suf=el.dataset.suffix||'';
  const reducedC=matchMedia('(prefers-reduced-motion: reduce)').matches;
  let s=null;const dur=1200;const f=n=>pre+n.toLocaleString('he-IL',{minimumFractionDigits:dec,maximumFractionDigits:dec})+suf;
  if(reducedC){el.textContent=f(to);return;}
  const step=t=>{if(!s)s=t;const p=Math.min(1,(t-s)/dur),e=1-Math.pow(1-p,3);el.textContent=f(to*e);
    el.style.filter='blur('+((1-e)*4).toFixed(2)+'px)'; /* numbers resolve into focus */
    if(p<1)requestAnimationFrame(step);else{el.textContent=f(to);el.style.filter='none';}};requestAnimationFrame(step);}
function watchCount(sel){const io=new IntersectionObserver((es)=>es.forEach(e=>{if(e.isIntersecting){e.target.querySelectorAll('[data-count]').forEach(countUp);io.unobserve(e.target)}}),{threshold:.35});document.querySelectorAll(sel).forEach(el=>io.observe(el));}
watchCount('.statgrid');

/* (The hero dashboard-mock chart block lived here. The mock was replaced by   the hero video, but the script kept observing #dash — observe(null) threw   on mount and the error boundary blanked the whole landing, 31 Aug 2026.) */

/* ===== AI agent cards: grab-and-throw (apple-design physics) ===== */
const FIND=[
  {tone:'blue',title:'הפוסטים שלכם מייצרים ביקוש',chips:['INSTAGRAM','ביטחון 88%'],
   ev:'סרקנו <span class="mono">14</span> פוסטים · <span class="mono">4,820</span> לייקים · <span class="mono">312</span> תגובות',
   act:'3 מתוך 5 המובילים הם וידאו מוצר — הפיקו עוד באותו פורמט, זה מה שמזיז.',learned:'המעורבות עולה עקבית כשיש וידאו בפוסט.'},
  {tone:'amber',title:'3 תאריכים שלא הצלחנו לסרוק',chips:['INSTAGRAM','ביטחון 73%'],
   ev:'בין <span class="mono">12–14.8</span> לא נמצא תוכן שמור לפרופיל',
   act:'העליתם וידאו או פוסט בתאריכים האלה? תייגו את המותג כדי שנמדוד אותם.',learned:'ייתכן שהיה פוסט אורגני חזק שעדיין לא נספר.'},
  {tone:'blue',title:'מנצח קריאייטיב ב־Meta',chips:['META ADS','ביטחון 82%'],
   ev:'Creative_A2 · <span class="mono">12</span> רכישות · <span class="mono">₪480</span> הוצאה · ROAS <span class="mono">6.8x</span>',
   act:'בנו 2־3 וריאציות סביב אותו hook — יש כאן זווית מנצחת.',learned:'חוזר גם משבועות קודמים — לא קפיצה חד־פעמית.'}
];
const stage=document.getElementById('stage'),N=FIND.length,dirSign=-1;
const cards=FIND.map(f=>{const el=document.createElement('div');el.className='fcard '+f.tone;
  el.innerHTML=`<div class="frow"><div class="ft">${f.title}</div><div class="chips">${f.chips.map(c=>`<span class="chip">${c}</span>`).join('')}</div></div>
    <div class="blk"><div class="bl">ראיה</div><div class="bt">${f.ev}</div></div>
    <div class="blk"><div class="bl">פעולה מומלצת</div><div class="bt">${f.act}</div></div>
    <div class="learned"><svg width="16" height="16" viewBox="0 0 24 24" fill="none"><path d="M12 3a9 9 0 1 0 9 9" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><path d="M12 7v5l3 2" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>${f.learned}</div>`;
  stage.appendChild(el);return el;});
const pagerEl=document.getElementById('pager');
const dots=FIND.map((f,i)=>{const d=document.createElement('button');d.className='dot';d.type='button';d.setAttribute('aria-label',f.title);d.addEventListener('click',()=>select(i));pagerEl.appendChild(d);return d;});
const project=(v,dr=0.998)=>(v/1000)*dr/(1-dr),rubberband=(o,dim=1,c=0.55)=>(o*dim*c)/(dim+c*Math.abs(o)),springK=(r,d)=>{const k=(2*Math.PI/r)**2;return{k,c:2*d*Math.sqrt(k)}};
let pos=0,vel=0,target=0,rafId=null,activeInt=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function paint(){const step=stage.clientWidth;for(let i=0;i<N;i++){const dist=i-pos,x=dist*step*dirSign,ad=Math.min(Math.abs(dist),1);
  cards[i].style.transform=`translate3d(${x}px,0,0) scale(${1-ad*0.045})`;cards[i].style.opacity=Math.max(0,1-Math.abs(dist)*0.75);
  cards[i].style.pointerEvents=Math.round(pos)===i?'auto':'none';cards[i].style.zIndex=String(100-Math.round(Math.abs(dist)*10));}
  const r=Math.round(pos);if(r!==activeInt&&r>=0&&r<N){activeInt=r;dots.forEach((d,j)=>d.setAttribute('aria-current',j===r));}}
function stop(){if(rafId){cancelAnimationFrame(rafId);rafId=null}}
function run(d){const{k,c}=springK(0.42,d);let last=performance.now();stop();const tick=n=>{const dt=Math.min(0.032,(n-last)/1000);last=n;
  const a=-k*(pos-target)-c*vel;vel+=a*dt;pos+=vel*dt;if(Math.abs(pos-target)<0.001&&Math.abs(vel)<0.02){pos=target;vel=0;paint();rafId=null;return}paint();rafId=requestAnimationFrame(tick)};rafId=requestAnimationFrame(tick)}
function animateTo(i,v=0,d=1){target=Math.max(0,Math.min(N-1,i));vel=v;if(reduced){pos=target;vel=0;paint();return}run(d)}
function select(i){animateTo(i)}
let drag=null;
stage.addEventListener('pointerdown',e=>{if(reduced)return;if(e.pointerType==='mouse'&&e.button!==0)return;stop();
  drag={id:e.pointerId,startX:e.clientX,startY:e.clientY,posAtGrab:pos,step:stage.clientWidth||1,committed:false,hist:[{x:e.clientX,t:e.timeStamp}]};
  addEventListener('pointermove',onMove,{passive:false});addEventListener('pointerup',onUp);addEventListener('pointercancel',onUp)});
function onMove(e){if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;
  if(!drag.committed){if(Math.abs(dx)<10&&Math.abs(dy)<10)return;if(Math.abs(dx)<=Math.abs(dy)){cleanup();drag=null;return}drag.committed=true;try{stage.setPointerCapture(drag.id)}catch(_){}}
  e.preventDefault();drag.hist.push({x:e.clientX,t:e.timeStamp});if(drag.hist.length>6)drag.hist.shift();
  let next=drag.posAtGrab-dx/(drag.step*dirSign);const mx=N-1;if(next<0)next=rubberband(next);else if(next>mx)next=mx+rubberband(next-mx);pos=next;vel=0;paint()}
function onUp(e){if(!drag||e.pointerId!==drag.id)return;cleanup();const d=drag;drag=null;if(!d.committed)return;
  const h=d.hist;let vpx=0;if(h.length>=2){const a=h[0],b=h[h.length-1],dt=(b.t-a.t)/1000;if(dt>0)vpx=(b.x-a.x)/dt;}
  const projPos=d.posAtGrab-((e.clientX-d.startX)+project(vpx))/(d.step*dirSign);animateTo(Math.max(0,Math.min(N-1,Math.round(projPos))),-vpx/(d.step*dirSign),0.82)}
function cleanup(){removeEventListener('pointermove',onMove);removeEventListener('pointerup',onUp);removeEventListener('pointercancel',onUp)}
addEventListener('resize',paint);paint();dots[0]&&dots[0].setAttribute('aria-current','true');

/* ===== Scroll-driven text color reveal (Adyen-style) ===== */
(function(){
  const els=[...document.querySelectorAll('.reveal-text')];
  const reducedRT=matchMedia('(prefers-reduced-motion: reduce)').matches;
  els.forEach(el=>{
    const words=el.textContent.trim().split(/\s+/);
    el.textContent='';
    words.forEach((w,i)=>{const s=document.createElement('span');s.className='rw';s.textContent=w;el.appendChild(s);
      if(i<words.length-1)el.appendChild(document.createTextNode(' '));});
    el._words=el.querySelectorAll('.rw');
  });
  function update(){
    els.forEach(el=>{
      const sp=el._words,r=el.getBoundingClientRect(),vh=innerHeight;
      const start=vh*0.82,end=vh*0.4;
      const p=Math.min(1,Math.max(0,(start-r.top)/(start-end)));
      const n=Math.round(p*sp.length);
      sp.forEach((s,i)=>s.classList.toggle('on',reducedRT||i<n));
    });
  }
  let ticking=false;
  addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(()=>{update();ticking=false;});}},{passive:true});
  addEventListener('resize',update);update();
})();

/* ===== Product carousel: arrows + RTL-safe, native scroll on touch ===== */
(function(){
  const car=document.getElementById('carousel');if(!car)return;
  const prev=document.getElementById('cPrev'),next=document.getElementById('cNext');
  const isRTL=getComputedStyle(car).direction==='rtl';
  const slides=()=>[...car.querySelectorAll('.cslide')];
  function curIdx(){
    const cr=car.getBoundingClientRect(),edge=isRTL?cr.right:cr.left;let best=0,bd=Infinity;
    slides().forEach((c,i)=>{const r=c.getBoundingClientRect(),ce=isRTL?r.right:r.left,d=Math.abs(ce-edge);if(d<bd){bd=d;best=i;}});
    return best;
  }
  function go(dir){const s=slides();const i=Math.min(s.length-1,Math.max(0,curIdx()+dir));
    s[i].scrollIntoView({behavior:'smooth',inline:'start',block:'nearest'});}
  function atStart(){const c=slides()[0].getBoundingClientRect(),cr=car.getBoundingClientRect();return isRTL?c.right<=cr.right+2:c.left>=cr.left-2;}
  function atEnd(){const s=slides(),c=s[s.length-1].getBoundingClientRect(),cr=car.getBoundingClientRect();return isRTL?c.left>=cr.left-2:c.right<=cr.right+2;}
  function upd(){prev.disabled=atStart();next.disabled=atEnd();}
  prev.addEventListener('click',()=>go(-1));next.addEventListener('click',()=>go(1));
  let t=false;car.addEventListener('scroll',()=>{if(!t){t=true;requestAnimationFrame(()=>{upd();t=false;});}},{passive:true});
  addEventListener('resize',upd);upd();
})();

/* ===== "Numbers → clarity" converge canvas (the slogan) ===== */
(function(){
  const wrap=document.getElementById('cv');if(!wrap)return;
  const canvas=document.getElementById('cvCanvas'),ctx=canvas.getContext('2d');
  const srcEls=[...wrap.querySelectorAll('.src')],coreEl=wrap.querySelector('.core');
  // Phone layout: the same ring as desktop, scaled — 5 pills down each side of
  // the hub (DOM order: 4 Shopify sources, 4 channels, competitors, influencers).
  const desktopPos=srcEls.map(el=>({top:el.style.top,left:el.style.left}));
  const MOBILE=[[6,18],[28,18],[50,18],[72,18],[6,82],[28,82],[50,82],[72,82],[94,18],[94,82]];
  function layout(){const mobile=wrap.clientWidth<=640;srcEls.forEach((el,i)=>{const m=mobile&&MOBILE[i];
    el.style.top=m?m[0]+'%':desktopPos[i].top;el.style.left=m?m[1]+'%':desktopPos[i].left;});}
  const reducedC=matchMedia('(prefers-reduced-motion: reduce)').matches;
  let W=0,H=0,srcPts=[],corePt={x:0,y:0},parts=[],raf=null,running=false,last=0,acc=0;
  function measure(){
    layout();
    const dpr=Math.min(2,devicePixelRatio||1),r=wrap.getBoundingClientRect();W=r.width;H=r.height;
    canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);
    const rel=el=>{const b=el.getBoundingClientRect();return{x:b.left-r.left+b.width/2,y:b.top-r.top+b.height/2};};
    srcPts=srcEls.map(rel);corePt=rel(coreEl);
  }
  const ease=t=>t<.5?2*t*t:1-Math.pow(-2*t+2,2)/2;
  function spawn(){const s=srcPts[Math.floor(Math.random()*srcPts.length)];if(!s)return;
    parts.push({sx:s.x,sy:s.y,t:0,sp:0.006+Math.random()*0.007,off:(Math.random()*2-1)*28,orange:Math.random()<0.25,r:1.5+Math.random()*1.9});}
  function draw(){
    ctx.clearRect(0,0,W,H);
    srcPts.forEach(s=>{ctx.strokeStyle='rgba(21,163,74,0.5)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(s.x,s.y);
      ctx.quadraticCurveTo((s.x+corePt.x)/2,(s.y+corePt.y)/2-12,corePt.x,corePt.y);ctx.stroke();});
    for(let i=parts.length-1;i>=0;i--){const p=parts[i];p.t+=p.sp;if(p.t>=1){parts.splice(i,1);continue;}
      const e=ease(p.t),nx=-(corePt.y-p.sy),ny=(corePt.x-p.sx),nl=Math.hypot(nx,ny)||1,arc=Math.sin(p.t*Math.PI)*p.off,a=Math.sin(p.t*Math.PI);
      const x=p.sx+(corePt.x-p.sx)*e+(nx/nl)*arc, y=p.sy+(corePt.y-p.sy)*e+(ny/nl)*arc;
      ctx.fillStyle=p.orange?`rgba(249,115,22,${(0.5*a).toFixed(3)})`:`rgba(21,163,74,${(0.55*a).toFixed(3)})`;
      ctx.beginPath();ctx.arc(x,y,p.r*(1-0.3*e),0,7);ctx.fill();}
  }
  function loop(now){if(!running)return;const dt=Math.min(50,now-last||16);last=now;acc+=dt;
    while(acc>36){spawn();acc-=36;}draw();raf=requestAnimationFrame(loop);}
  function start(){if(running||reducedC)return;if(getComputedStyle(canvas).display==='none')return;running=true;last=0;raf=requestAnimationFrame(loop);}
  function stop(){running=false;if(raf)cancelAnimationFrame(raf);raf=null;}
  let counted=false;
  function coreCount(){if(counted)return;counted=true;const el=document.getElementById('coreNum');
    if(!el)return; /* hub has no number now — brain/hub style */
    const to=+el.dataset.count,pre=el.dataset.prefix||'';let s=null,dur=1500;const f=n=>pre+Math.round(n).toLocaleString('he-IL');
    if(reducedC){el.textContent=f(to);return;}
    const step=t=>{if(!s)s=t;const p=Math.min(1,(t-s)/dur),e=1-Math.pow(1-p,3);el.textContent=f(to*e);
      el.style.filter='blur('+((1-e)*6).toFixed(2)+'px)';if(p<1)requestAnimationFrame(step);else{el.textContent=f(to);el.style.filter='none';}};
    requestAnimationFrame(step);}
  measure();addEventListener('resize',()=>{measure();if(reducedC)draw();});
  if(reducedC)draw();
  new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){start();coreCount();}else stop();}),{threshold:.25}).observe(wrap);
})();

/* ===== Pricing: monthly / annual toggle ===== */
(function(){
  const seg=document.getElementById('billseg'); if(!seg)return;
  const btns=[...seg.querySelectorAll('button')];
  const prices=[...document.querySelectorAll('.plan .price[data-m]')];
  function set(mode){
    btns.forEach(b=>b.setAttribute('aria-current', String(b.dataset.mode===mode)));
    prices.forEach(p=>{
      p.querySelector('.amt').textContent = mode==='a'? p.dataset.a : p.dataset.m;
      const note=p.querySelector('.note');
      if(note) note.style.display = (mode==='a' && p.dataset.a!==p.dataset.m) ? 'block':'none';
    });
  }
  btns.forEach(b=>b.addEventListener('click',()=>set(b.dataset.mode)));
  set('m');
})();

}
